// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public {
        c = new LRTDepositPool();
    }

    function testFuzz_property(address newConfig, address nonAdmin) public {
        vm.assume(newConfig != address(0));
        vm.assume(nonAdmin != address(this));
        vm.assume(nonAdmin != address(0));

        vm.prank(nonAdmin);
        bool ok;
        try c.updateLRTConfig(newConfig) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "Non-admin updated LRT config - access control broken");
    }
}
